1355	// runTrailUpdateWithClientAtPath applies a trail update once the repo route and
1356	// API client are resolved.
1357	func runTrailUpdateWithClientAtPath(ctx context.Context, w io.Writer, client *api.Client, basePath string, inputs trailUpdateInputs) error {
1358		// Determine branch.
1359		branch := inputs.Branch
1360		if branch == "" {
1361			current, err := GetCurrentBranch(ctx)
1362			if err != nil {
1363				return fmt.Errorf("failed to determine current branch: %w", err)
1364			}
1365			branch = current
1366		}
1367	
1368		// Find the trail by branch.
1369		found, err := findTrailByBranchAtPath(ctx, client, basePath, branch)
1370		if err != nil {
1371			return err
1372		}
1373		if found == nil {
1374			return fmt.Errorf("no trail found for branch %q", branch)
1375		}
1376	
1377		// Interactive mode when no update flags are provided.
1378		statusStr := inputs.Status
1379		title := inputs.Title
1380		body := inputs.Body
1381		var bodyETag string
1382		noFlags := !inputs.StatusChanged && !inputs.TitleChanged && !inputs.BodyChanged &&
1383			inputs.AssigneeAdd == nil && inputs.AssigneeRemove == nil &&
1384			inputs.ReviewerAdd == nil && inputs.ReviewerRemove == nil &&
1385			!inputs.TypeChanged && !inputs.PriorityChanged
1386		if noFlags {
1387			metadata := found.ToMetadata()
1388			// Build status options with current value as default.
1389			var statusOptions []huh.Option[string]
1390			for _, s := range trail.ValidStatuses() {
1391				if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
1392					continue
1393				}
1394				label := string(s)
1395				if s == metadata.Status {
1396					label += " (current)"
1397				}
1398				statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
1399			}
1400			statusStr = string(metadata.Status)
1401			title = metadata.Title
1402			// The list resource omits the description; fetch the detail body so
1403			// the form prefills with the current text and change detection below
1404			// compares against the real server value.
1405			seedBody, seedETag, bodyErr := resolveTrailUpdateBodyAtPath(ctx, client, basePath, found)
1406			if bodyErr != nil {
1407				return fmt.Errorf("could not load current trail body: %w", bodyErr)
1408			}
1409			body = seedBody
1410			bodyETag = seedETag
1411			origStatus, origTitle, origBody := statusStr, title, body
1412	
1413			form := NewAccessibleForm(
1414				huh.NewGroup(
1415					huh.NewSelect[string]().
1416						Title("Status").
1417						Options(statusOptions...).
1418						Value(&statusStr),
1419					huh.NewInput().
1420						Title("Title").
1421						Value(&title),
1422					huh.NewText().
1423						Title("Body").
1424						Value(&body),
1425				),
1426			)
1427			if formErr := form.Run(); formErr != nil {
1428				return handleFormCancellation(w, "Trail update", formErr)
1429			}
1430			// Only mark a field changed when the user actually edited it, so an
1431			// untouched body/title/status isn't needlessly PATCHed (a no-op body
1432			// PATCH would otherwise rewrite the description on every update).
1433			inputs.StatusChanged = statusStr != origStatus
1434			inputs.TitleChanged = title != origTitle
1435			inputs.BodyChanged = body != origBody
1436		}
1437	
1438		statusStr = strings.TrimSpace(statusStr)
1439		title = strings.TrimSpace(title)
1440		if err := validateTrailUpdateFields(trailUpdateInputs{
1441			Status:          statusStr,
1442			StatusChanged:   inputs.StatusChanged,
1443			Title:           title,
1444			TitleChanged:    inputs.TitleChanged,
1445			Type:            inputs.Type,
1446			TypeChanged:     inputs.TypeChanged,
1447			Priority:        inputs.Priority,
1448			PriorityChanged: inputs.PriorityChanged,
1449		}); err != nil {
1450			return err
1451		}
1452	
1453		// Build the metadata request with only changed fields. The description is
1454		// not part of it — it is written separately, from the `body` local below.
1455		updateReq := buildTrailUpdateRequest(found, trailUpdateInputs{
1456			Status:          statusStr,
1457			StatusChanged:   inputs.StatusChanged,
1458			Title:           title,
1459			TitleChanged:    inputs.TitleChanged,
1460			AssigneeAdd:     inputs.AssigneeAdd,
1461			AssigneeRemove:  inputs.AssigneeRemove,
1462			ReviewerAdd:     inputs.ReviewerAdd,
1463			ReviewerRemove:  inputs.ReviewerRemove,
1464			Type:            inputs.Type,
1465			TypeChanged:     inputs.TypeChanged,
1466			Priority:        inputs.Priority,
1467			PriorityChanged: inputs.PriorityChanged,
1468		})
1469	
1470		// The single-trail endpoint is keyed by trail number, not id; the server
1471		// rejects an id here with "Invalid trail number format".
1472		if found.Number <= 0 {
1473			return fmt.Errorf("trail for branch %q has no number yet; cannot update", branch)
1474		}
1475		path := trailNumberPathForBase(basePath, found.Number)
1476	
1477		// Metadata and description live on different routes, so an update touching
1478		// both sends two requests. They are not atomic: if the metadata PATCH lands
1479		// and the body PUT then fails, the metadata change persists. Report that
1480		// partial state explicitly so the caller knows the metadata already applied
1481		// and only the body needs a retry, rather than assuming nothing changed.
1482		hasMeta := trailUpdateRequestHasFields(updateReq)
1483		if !hasMeta && !inputs.BodyChanged {
1484			// Nothing changed — most often the interactive form opened and closed
1485			// untouched. Say so instead of printing the success line: no request went
1486			// out, and agents read that line as confirmation the write landed.
1487			fmt.Fprintf(w, "No changes to apply to the trail for branch %s\n", branch)
1488			return nil
1489		}
1490		if !noFlags && inputs.BodyChanged && bodyETag == "" && !inputs.Overwrite {
1491			// Non-interactive --body path only. The interactive branch already
1492			// read the body and its etag to seed the editor. A --body caller
1493			// supplied replacement text directly and skipped that read, so do it
1494			// here purely for the etag. This must happen before the metadata PATCH
1495			// so a verification failure cannot partially apply a combined update.
1496			_, etag, ferr := fetchTrailDescriptionAtPath(ctx, client, basePath, found.Number)
1497			if ferr != nil {
1498				return fmt.Errorf("could not verify trail body is unchanged: %w", ferr)
1499			}
1500			bodyETag = etag
1501		}
1502		if hasMeta {
1503			if err := sendTrailPatch(ctx, client, path, updateReq); err != nil {
1504				return err
1505			}
1506		}
1507		if inputs.BodyChanged {
1508			if err := sendTrailBody(ctx, client, trailBodyPathForBase(basePath, found.Number), body, bodyETag, inputs.Overwrite); err != nil {
1509				if hasMeta {
1510					return fmt.Errorf("trail metadata was updated, but the body update failed (the metadata change already applied; retry only the --body change): %w", err)
1511				}
1512				return err
1513			}
1514		}
1515	
1516		fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
1517		return nil
1518	}
