1590	// buildTrailUpdateRequest constructs the metadata PATCH body from the current
1591	// trail and the requested changes. It deliberately ignores inputs.Body: the
1592	// description is not part of this request, it is written by sendTrailBody
1593	// against its own route, and api.TrailUpdateRequest has no field to put it in.
1594	func buildTrailUpdateRequest(current *api.TrailResource, inputs trailUpdateInputs) api.TrailUpdateRequest {
1595		var req api.TrailUpdateRequest
1596	
1597		if inputs.StatusChanged {
1598			req.Status = &inputs.Status
1599		}
1600		if inputs.TitleChanged {
1601			req.Title = &inputs.Title
1602		}
1603		if inputs.TypeChanged {
1604			typ := strings.TrimSpace(inputs.Type)
1605			req.Type = &typ
1606		}
1607		if inputs.PriorityChanged {
1608			priority := strings.TrimSpace(inputs.Priority)
1609			req.Priority = &priority
1610		}
1611		// Replace-set fields: compute the full new list from the current trail.
1612		if len(inputs.AssigneeAdd) > 0 || len(inputs.AssigneeRemove) > 0 {
1613			assignees := mergeStringSet(current.Assignees, inputs.AssigneeAdd, inputs.AssigneeRemove)
1614			req.Assignees = &assignees
1615		}
1616		if len(inputs.ReviewerAdd) > 0 || len(inputs.ReviewerRemove) > 0 {
1617			reviewers := mergeStringSet(current.RequestedReviewers, inputs.ReviewerAdd, inputs.ReviewerRemove)
1618			req.RequestedReviewers = &reviewers
1619		}
1620	
1621		return req
1622	}
