1241	// resolveTrailUpdateBody returns the body text to seed the interactive update
1242	// form with, plus the etag of the description as read (empty when unavailable,
1243	// e.g. an older server or a fallback to the list body — see sendTrailBody for
1244	// how a missing etag is handled). The list resource omits the description (it
1245	// lives in body_document, served only by the detail endpoint), so update must
1246	// fetch the detail body — otherwise the form prefills from the empty list body
1247	// and a user edit against that blank baseline can overwrite a description they
1248	// never saw. On a failed detail fetch it returns the list body (and no etag)
1249	// plus the error so the caller can stop before opening the editor; an empty
1250	// detail body (older/partial server) falls back to the list body with no error.
1251	func resolveTrailUpdateBodyAtPath(ctx context.Context, client *api.Client, basePath string, found *api.TrailResource) (body, etag string, err error) {
1252		body = found.Body
1253		if found.Number > 0 {
1254			bt, et, ferr := fetchTrailDescriptionAtPath(ctx, client, basePath, found.Number)
1255			if ferr != nil {
1256				return body, "", ferr
1257			}
1258			// fetchTrailDescription already trims; a non-empty result supersedes
1259			// the list body, an empty one (older/partial server) leaves it intact.
1260			// The etag is kept either way — it describes the document read, not
1261			// the text, so it's valid even when the description is legitimately
1262			// empty (avoids a redundant refetch below).
1263			etag = et
1264			if bt != "" {
1265				body = bt
1266			}
1267		}
1268		return body, etag, nil
1269	}
