1415					huh.NewSelect[string]().
1416						Title("Status").
1417						Options(statusOptions...).
1418						Value(&statusStr),
1419					huh.NewInput().
1420						Title("Title").
1421						Value(&title),
1422					huh.NewText().
1423						Title("Body").
1424						Value(&body),
