1624	// trailUpdateRequestHasFields reports whether req sets any field at all. It
1625	// walks the struct reflectively rather than naming each field, so a field added
1626	// to api.TrailUpdateRequest later — a branch rename, say — counts as a metadata
1627	// change without anyone having to remember to extend this check. Forgetting to
1628	// would drop that change silently: the PATCH is never sent, yet the command
1629	// still reports success.
1630	//
1631	// The reflective default is only right for fields the metadata route actually
1632	// serves. A field that has to travel with the description instead — a
1633	// hypothetical body_format or body_version — belongs in api.TrailBodyRequest
1634	// and on the body PUT; put it here and it goes out on a route that does not
1635	// know it, which is the same wrong-route mistake the body itself used to make.
1636	func trailUpdateRequestHasFields(req api.TrailUpdateRequest) bool {
1637		v := reflect.ValueOf(req)
1638		for i := range v.NumField() {
1639			// Every field is a pointer today (nil means "not provided"), but IsZero
1640			// also covers a plain string or slice field added later.
1641			if !v.Field(i).IsZero() {
1642				return true
1643			}
1644		}
1645		return false
1646	}
